import{_ as l,I as t,o as e,c as r,b6 as i,j as s,J as h,w as g}from"./chunks/framework.BUXTSoD9.js";const f=JSON.parse('{"title":"Thực hành phát triển SaaS tạo ảnh AI hiện đại","description":"","frontmatter":{},"headers":[],"relativePath":"vi-vn/stage-2/assignments/modern-landing-page/index.md","filePath":"vi-vn/stage-2/assignments/modern-landing-page/index.md"}'),d={name:"vi-vn/stage-2/assignments/modern-landing-page/index.md"},o={style:{margin:"32px 0"}};function u(p,n,k,m,b,v){const a=t("StepBar"),c=t("ClientOnly");return e(),r("div",null,[n[0]||(n[0]=i('<h1 id="thuc-hanh-phat-trien-saas-tao-anh-ai-hien-đai" tabindex="-1">Thực hành phát triển SaaS tạo ảnh AI hiện đại <a class="header-anchor" href="#thuc-hanh-phat-trien-saas-tao-anh-ai-hien-đai" aria-label="Permalink to “Thực hành phát triển SaaS tạo ảnh AI hiện đại”">​</a></h1><h2 id="tong-quan" tabindex="-1">Tổng quan <a class="header-anchor" href="#tong-quan" aria-label="Permalink to “Tổng quan”">​</a></h2><p>Dự án thực chiến này yêu cầu bạn hoàn thành một sản phẩm SaaS tạo ảnh AI tham khảo trải nghiệm Midjourney dựa trên một PRD (tài liệu yêu cầu sản phẩm) thực tế, xây dựng từ đầu. Bạn sẽ trải nghiệm toàn bộ quá trình phân tích yêu cầu, phân tách dự án, phát triển lặp, liên hợp và triển khai.</p><p>Đây là phần thực hành tổng hợp của Stage 2. Trong các chương trước, bạn đã học riêng biệt các kỹ năng thiết kế trang frontend, phát triển API backend, thao tác cơ sở dữ liệu, tích hợp thanh toán, v.v. — dự án này yêu cầu bạn kết hợp tất cả lại với nhau, bàn giao một nguyên mẫu sản phẩm có thể chạy được.</p><h2 id="kien-thuc-tien-quyet" tabindex="-1">Kiến thức tiên quyết <a class="header-anchor" href="#kien-thuc-tien-quyet" aria-label="Permalink to “Kiến thức tiên quyết”">​</a></h2><p>Trước khi bắt đầu dự án này, bạn nên đã nắm được các nội dung sau:</p><ul><li>Thiết kế trang frontend và sử dụng thư viện component (<a href="./../../frontend/ui-design/">Thiết kế UI</a>, <a href="./../../frontend/modern-component-library/">Thư viện component hiện đại</a>)</li><li>Thiết kế và phát triển API backend (<a href="./../../backend/ai-interface-code/">Viết code API</a>)</li><li>Cơ sở dữ liệu cơ bản và Supabase (<a href="./../../backend/database-supabase/">Từ cơ sở dữ liệu đến Supabase</a>)</li><li>Tích hợp thanh toán (<a href="./../../backend/stripe-payment/">Hệ thống thanh toán Stripe</a>)</li><li>Quy trình làm việc Git và triển khai (<a href="./../../backend/git-workflow/">Git và GitHub</a>, <a href="./../../backend/zeabur-deployment/">Triển khai ứng dụng Web</a>)</li></ul><h2 id="muc-tieu-hoc-tap" tabindex="-1">Mục tiêu học tập <a class="header-anchor" href="#muc-tieu-hoc-tap" aria-label="Permalink to “Mục tiêu học tập”">​</a></h2><p>Sau khi hoàn thành bài thực hành này, bạn sẽ có thể:</p><ol><li>Đọc và hiểu một PRD thực tế, từ đó trích xuất danh sách công việc phát triển</li><li>Phân tách module dựa trên PRD, lập kế hoạch triển khai từng bước</li><li>Sử dụng AI hỗ trợ hoàn thành xây dựng khung frontend và phát triển API backend</li><li>Xác minh và tối ưu hóa lặp từng module</li><li>Hoàn thành liên hợp đầu cuối, đưa dự án từ &quot;chạy được&quot; đến &quot;có thể bàn giao&quot;</li></ol><h2 id="gioi-thieu-du-an" tabindex="-1">Giới thiệu dự án <a class="header-anchor" href="#gioi-thieu-du-an" aria-label="Permalink to “Giới thiệu dự án”">​</a></h2><p>Sản phẩm bạn cần xây dựng là một nền tảng SaaS tạo ảnh AI hiện đại, bao gồm ba hệ thống con:</p><table tabindex="0"><thead><tr><th>Hệ thống con</th><th>Trách nhiệm</th></tr></thead><tbody><tr><td><strong>Trang chủ</strong></td><td>Giới thiệu sản phẩm, bảng giá, FAQ, chuyển đổi đăng ký</td></tr><tr><td><strong>Bàn làm việc người dùng</strong></td><td>Nhập Prompt, tạo ảnh, thư viện ảnh, tín dụng, gói dịch vụ, tương tác cộng đồng</td></tr><tr><td><strong>Back-office quản trị</strong></td><td>Quản lý người dùng, quản lý tác vụ, quản lý thanh toán, kiểm duyệt nội dung, chỉ số SaaS, giám sát hệ thống</td></tr></tbody></table><p>Backend cần hỗ trợ các khả năng cốt lõi sau: xác thực người dùng, tác vụ tạo ảnh, lưu trữ đối tượng OSS, tín dụng và thanh toán gói dịch vụ, tương tác xã hội ảnh, giám sát dữ liệu vận hành.</p><div class="tip custom-block"><p class="custom-block-title">Đường dẫn PRD</p><p>Tài liệu yêu cầu của dự án này nằm trên GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/modern-landing-page/PRD.md" target="_blank" rel="noreferrer">Xem PRD</a></p></div>',15)),s("div",o,[h(c,null,{default:g(()=>[h(a,{active:0,items:[{title:"Phân tích yêu cầu",description:"Đọc PRD, trích xuất trang, module, mô hình dữ liệu và ranh giới"},{title:"Xây dựng khung",description:"Dùng AI tạo ba bộ khung frontend (www / app / admin)"},{title:"Phát triển lặp",description:"Bổ sung từng module: API, phân quyền, thanh toán, giám sát"},{title:"Liên hợp & triển khai",description:"Chạy đầu cuối, triển khai và chuẩn bị demo"}]})]),_:1})]),n[1]||(n[1]=i(`<h2 id="phan-1-phan-tich-yeu-cau" tabindex="-1">Phần 1: Phân tích yêu cầu <a class="header-anchor" href="#phan-1-phan-tich-yeu-cau" aria-label="Permalink to “Phần 1: Phân tích yêu cầu”">​</a></h2><h3 id="_1-1-đoc-prd" tabindex="-1">1.1 Đọc PRD <a class="header-anchor" href="#_1-1-đoc-prd" aria-label="Permalink to “1.1 Đọc PRD”">​</a></h3><p>Mở tài liệu PRD, tập trung trả lời các câu hỏi sau:</p><ul><li>Hệ thống có mấy điểm vào? Mỗi điểm bao phủ những trang nào?</li><li>Chức năng cốt lõi của mỗi trang là gì?</li><li>Backend bao gồm những module và bảng cơ sở dữ liệu nào?</li><li>Phạm vi MVP là gì? Phiên bản đầu tiên làm gì, không làm gì?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Nếu các câu hỏi trên chưa có câu trả lời rõ ràng, đừng bắt đầu viết code. Hiểu sai yêu cầu là nguyên nhân phổ biến nhất dẫn đến phải làm lại.</p></div><h3 id="_1-2-xac-nhan-kien-truc-he-thong" tabindex="-1">1.2 Xác nhận kiến trúc hệ thống <a class="header-anchor" href="#_1-2-xac-nhan-kien-truc-he-thong" aria-label="Permalink to “1.2 Xác nhận kiến trúc hệ thống”">​</a></h3><p>Dựa trên mô tả trong PRD, hệ thống hóa kiến trúc tổng thể của hệ thống:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;Trang chủ&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;Bàn làm việc người dùng&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;Back-office quản trị&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;Xác thực&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;Tác vụ tạo ảnh&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; oss[&quot;Lưu trữ đối tượng OSS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;Cơ sở dữ liệu&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;Thanh toán &amp; gói dịch vụ&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  social[&quot;Chia sẻ / Thích / Bình luận / Chuyển tiếp&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;Bảng chỉ số SaaS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; observability[&quot;Giám sát API / DB / Provider&quot;]</span></span></code></pre></div><p>Khuyến nghị bạn vẽ lại sơ đồ kiến trúc bằng lời của mình, xác nhận rằng sự hiểu biết của bạn về hệ thống là hoàn chỉnh.</p><h2 id="phan-2-xay-dung-khung-du-an" tabindex="-1">Phần 2: Xây dựng khung dự án <a class="header-anchor" href="#phan-2-xay-dung-khung-du-an" aria-label="Permalink to “Phần 2: Xây dựng khung dự án”">​</a></h2><h3 id="_2-1-tao-trang-frontend" tabindex="-1">2.1 Tạo trang frontend <a class="header-anchor" href="#_2-1-tao-trang-frontend" aria-label="Permalink to “2.1 Tạo trang frontend”">​</a></h3><p>Sử dụng AI để tạo cấu trúc cơ bản và dữ liệu giả cho tất cả các trang. Mục tiêu của bước này là tạo ra kiến trúc thông tin và định tuyến, không cần kết nối API thực tế.</p><p>Tham khảo prompt:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Vui lòng dựa trên PRD hiện tại, giúp tôi tạo khung frontend của SaaS tạo ảnh AI hiện đại.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Yêu cầu:</span></span>
<span class="line"><span>1. Chia thành ba điểm vào: www, app, admin</span></span>
<span class="line"><span>2. Trang chủ bao gồm: trang chủ, bảng giá, FAQ</span></span>
<span class="line"><span>3. app bao gồm: đăng nhập, đăng ký, bàn làm việc tạo ảnh, thư viện ảnh, gói dịch vụ, tín dụng, cộng đồng, chi tiết tác phẩm, trang cá nhân</span></span>
<span class="line"><span>4. admin bao gồm: trang chủ back-office, quản lý người dùng, quản lý tác vụ, quản lý nội dung, quản lý gói dịch vụ, đơn thanh toán, cấu hình vận hành, chỉ số SaaS, giám sát hệ thống</span></span>
<span class="line"><span>5. Trước tiên chỉ tạo cấu trúc trang và dữ liệu giả, không kết nối API thực tế</span></span>
<span class="line"><span>6. Phong cách tham khảo Midjourney, đơn giản, hiện đại, có cảm giác sản phẩm</span></span></code></pre></div><h3 id="_2-2-xac-minh-cau-truc-trang" tabindex="-1">2.2 Xác minh cấu trúc trang <a class="header-anchor" href="#_2-2-xac-minh-cau-truc-trang" aria-label="Permalink to “2.2 Xác minh cấu trúc trang”">​</a></h3><p>Sau khi tạo khung, kiểm tra từng mục:</p><ul><li>[ ] Định tuyến của ba điểm vào có độc lập không (<code>/</code>, <code>/app</code>, <code>/admin</code>)</li><li>[ ] Số lượng trang có khớp với PRD không</li><li>[ ] Mỗi trang có thể truy cập và điều hướng bình thường không</li><li>[ ] Dữ liệu giả có hiển thị trạng thái UI cơ bản không (danh sách, trạng thái trống, biểu mẫu, v.v.)</li></ul><h2 id="phan-3-phat-trien-lap" tabindex="-1">Phần 3: Phát triển lặp <a class="header-anchor" href="#phan-3-phat-trien-lap" aria-label="Permalink to “Phần 3: Phát triển lặp”">​</a></h2><h3 id="_3-1-trien-khai-theo-module" tabindex="-1">3.1 Triển khai theo module <a class="header-anchor" href="#_3-1-trien-khai-theo-module" aria-label="Permalink to “3.1 Triển khai theo module”">​</a></h3><p>Trên cơ sở khung, bổ sung chức năng theo thứ tự module sau:</p><ol><li><strong>Xác thực</strong>: Đăng ký, đăng nhập, phân biệt vai trò</li><li><strong>Cơ sở dữ liệu</strong>: Tạo bảng dữ liệu, API đọc/ghi</li><li><strong>Nghiệp vụ cốt lõi</strong>: Tác vụ tạo ảnh, lưu trữ kết quả</li><li><strong>Lưu trữ OSS</strong>: Tải lên và truy cập ảnh</li><li><strong>Thanh toán</strong>: Gói dịch vụ, tín dụng, tích hợp Stripe</li><li><strong>Tương tác xã hội</strong>: Chia sẻ, thích, bình luận</li><li><strong>Quản lý back-office</strong>: Quản lý người dùng, quản lý tác vụ, kiểm duyệt nội dung</li><li><strong>Giám sát dữ liệu</strong>: Bảng chỉ số SaaS, giám sát hệ thống</li></ol><p>Sau khi hoàn thành mỗi module, sử dụng bảng dưới đây để tự kiểm tra:</p><table tabindex="0"><thead><tr><th>Mục kiểm tra</th><th>Phương pháp xác minh</th></tr></thead><tbody><tr><td>Tính nhất quán trang</td><td>Số lượng trang, điểm vào, chức năng có khớp với PRD không</td></tr><tr><td>Tính chính xác API</td><td>Tham số yêu cầu, cấu trúc trả về, xử lý trạng thái có hợp lý không</td></tr><tr><td>Cách ly phân quyền</td><td>Người dùng thông thường và quản trị viên có cách ly nhau không</td></tr><tr><td>Tính nhất quán dữ liệu</td><td>Cơ sở dữ liệu, OSS, thanh toán, tín dụng có khớp nhau không</td></tr><tr><td>Khả năng demo</td><td>Có thể demo hoàn chỉnh một chuỗi nghiệp vụ cho người khác không</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Nếu phát hiện nội dung do AI tạo ra sai lệch so với PRD, đừng lật đổ toàn bộ trang, hãy để AI sửa trực tiếp module cụ thể.</p></div><h3 id="_3-2-vai-tro-va-phan-cong" tabindex="-1">3.2 Vai trò và phân công <a class="header-anchor" href="#_3-2-vai-tro-va-phan-cong" aria-label="Permalink to “3.2 Vai trò và phân công”">​</a></h3><p>Trong quá trình lặp, bạn cần đóng đồng thời ba vai trò:</p><ul><li><strong>Quản lý sản phẩm</strong>: Xác nhận chức năng của mỗi module có khớp với PRD không</li><li><strong>Trưởng nhóm kỹ thuật</strong>: Xác nhận phương án triển khai có hợp lý không</li><li><strong>Kỹ sư kiểm thử</strong>: Xác nhận chức năng có chạy được không</li></ul><h2 id="phan-4-lien-hop-va-trien-khai" tabindex="-1">Phần 4: Liên hợp và Triển khai <a class="header-anchor" href="#phan-4-lien-hop-va-trien-khai" aria-label="Permalink to “Phần 4: Liên hợp và Triển khai”">​</a></h2><h3 id="_4-1-kiem-thu-đau-cuoi" tabindex="-1">4.1 Kiểm thử đầu cuối <a class="header-anchor" href="#_4-1-kiem-thu-đau-cuoi" aria-label="Permalink to “4.1 Kiểm thử đầu cuối”">​</a></h3><p>Trọng tâm của giai đoạn cuối không phải là bổ sung trang mới, mà là chạy qua toàn bộ chuỗi nghiệp vụ. Ít nhất xác minh các kịch bản sau:</p><ul><li>Đăng ký → Mua tín dụng → Tạo ảnh → Xem lịch sử → Chia sẻ tương tác</li><li>Quản trị viên đăng nhập → Xem dữ liệu người dùng → Xem thống kê tác vụ → Xem giám sát hệ thống</li></ul><h3 id="_4-2-trien-khai" tabindex="-1">4.2 Triển khai <a class="header-anchor" href="#_4-2-trien-khai" aria-label="Permalink to “4.2 Triển khai”">​</a></h3><p>Triển khai dự án lên môi trường mạng công cộng, đảm bảo:</p><ul><li>Cấu hình biến môi trường hoàn chỉnh</li><li>Địa chỉ callback đăng nhập chính xác</li><li>Địa chỉ callback thanh toán chính xác</li><li>Trang không thiếu trạng thái loading, trạng thái trống, thông báo lỗi</li></ul><p>Tham khảo hướng dẫn triển khai: <a href="./../../backend/git-workflow/">Quy trình làm việc Git và GitHub</a>, <a href="./../../backend/zeabur-deployment/">Cách triển khai ứng dụng Web</a>.</p><h2 id="san-pham-ban-giao" tabindex="-1">Sản phẩm bàn giao <a class="header-anchor" href="#san-pham-ban-giao" aria-label="Permalink to “Sản phẩm bàn giao”">​</a></h2><p>Sau khi hoàn thành dự án này, bạn cần nộp các nội dung sau:</p><ul><li>[ ] Liên kết demo trực tuyến có thể truy cập</li><li>[ ] Liên kết kho mã nguồn (bao gồm README)</li><li>[ ] Tài liệu PRD</li><li>[ ] Ảnh chụp màn hình các trang cốt lõi (trang chủ website, bàn làm việc tạo ảnh, thư viện ảnh, trang gói dịch vụ, trang chủ back-office)</li><li>[ ] Video demo 60 giây (bao gồm đăng ký → tạo ảnh → xem → quản lý back-office)</li></ul><p>README tối thiểu bao gồm: giới thiệu dự án, mô tả trang cốt lõi, công nghệ sử dụng, bước khởi động cục bộ, danh sách biến môi trường.</p><h2 id="tieu-chi-cham-điem" tabindex="-1">Tiêu chí chấm điểm <a class="header-anchor" href="#tieu-chi-cham-điem" aria-label="Permalink to “Tiêu chí chấm điểm”">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Yêu cầu cơ bản</th><th>Yêu cầu nâng cao</th></tr></thead><tbody><tr><td>Căn chỉnh PRD</td><td>Trang, chức năng, cấu trúc dữ liệu cơ bản khớp với PRD</td><td>Có thể giải thích rõ ràng mỗi quyết định thiết kế tương ứng với PRD như thế nào</td></tr><tr><td>Chuỗi sản phẩm</td><td>Đăng ký → Mua tín dụng → Tạo ảnh → Xem lịch sử → Chia sẻ tương tác có thể chạy qua</td><td>Trạng thái thanh toán, số dư tín dụng, số lần tạo ảnh nhất quán về dữ liệu</td></tr><tr><td>Khả năng back-office</td><td>Người dùng, tác vụ, thanh toán, quản lý nội dung có thể xem</td><td>Bảng chỉ số SaaS và trang giám sát hệ thống hoàn chỉnh có thể sử dụng</td></tr><tr><td>Độ hoàn thiện kỹ thuật</td><td>Frontend, backend, cơ sở dữ liệu, OSS, chuỗi thanh toán đã kết nối</td><td>Có xử lý lỗi, trạng thái trống, trạng thái loading</td></tr><tr><td>Chất lượng bàn giao</td><td>Có thể triển khai, có thể chạy</td><td>README rõ ràng, cấu trúc video demo hoàn chỉnh</td></tr></tbody></table><h2 id="tai-lieu-tham-khao" tabindex="-1">Tài liệu tham khảo <a class="header-anchor" href="#tai-lieu-tham-khao" aria-label="Permalink to “Tài liệu tham khảo”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Thiết kế UI</a></li><li><a href="./../../frontend/multi-product-ui/">Tham khảo quy phạm thiết kế UI để thiết kế trang và nút</a></li><li><a href="./../../frontend/llm-skills-beautiful/">Dùng LLM và Skills làm cho giao diện đẹp hơn</a></li><li><a href="./../../frontend/design-to-code/">Từ nguyên mẫu thiết kế đến code dự án</a></li><li><a href="./../../frontend/modern-component-library/">Sử dụng thư viện component hiện đại để cập nhật giao diện</a></li><li><a href="./../../backend/database-supabase/">Từ cơ sở dữ liệu đến Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Mô hình hỗ trợ viết code API và tài liệu API bằng mô hình lớn</a></li><li><a href="./../../backend/git-workflow/">Quy trình làm việc Git và GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Cách triển khai ứng dụng Web</a></li><li><a href="./../../backend/stripe-payment/">Cách tích hợp hệ thống thanh toán như Stripe</a></li></ul>`,43))])}const P=l(d,[["render",u]]);export{f as __pageData,P as default};
